  "prediction_basis_card_ids": [
    "C02", "C16", "C25", "C26", "C01", "C07", "C19", "C06",
    "C66", "C71", "C74", "C76"
  ],
  "claims": [
    {
      "claim": "Directly measured oral bioavailability in humans/rats for related phenolic natural products is consistently below 20%: chrysin <1% (C02) and predicted 0.003–0.02% (C16); acacetin poor due to glucuronidation and BCRP/MRP2 efflux (C25); 7,8-benzoflavone 13.2% (C26); anthocyanins 0.14–0.48% (C01, C03, C05, C10, C11, C12, C17); curcumin poor (C07, C13, C14, C19); flavonolignans very low by CL/F (C06, C08, C09, C15, C18).",
      "card_ids": [
        "C02", "C16", "C25", "C26", "C01", "C03", "C05", "C10", "C11", "C12", "C17",
        "C07", "C13", "C14", "C19", "C06", "C08", "C09", "C15", "C18"
      ]
    },
    {
      "claim": "L6 hepatic/metabolic records show related 7-hydroxy/methoxy phenolics undergo glucuronidation: wogonin and oroxylin A by UGT1A8/1A9 (C68, C74), wogonin glucuronidation very fast in rat liver microsomes/intestine S9 (C66, C71), calycosin by UGT1A1/1A10 (C77), and a 7-hydroxy-3-(4-fluorophenyl)coumarin predominantly by UGT1A10 (C76). Scopoletin's 7-OH/6-OMe pattern is a plausible UGT substrate, supporting presystemic loss.",
      "card_ids": ["C66", "C68", "C71", "C74", "C76", "C77"]
    },
    {
      "claim": "L4/L5 permeability and no-efflux records for other molecules (decursin efflux ratio 1.0, C56/C65; formononetin passive diffusion, C57; calycosin passive diffusion, C58; prunetin/biochanin A moderate-high permeability, C55/C61) support the absorption component but do not provide scopoletin-specific systemic F or overcome the metabolic-loss evidence.",
      "card_ids": ["C56", "C65", "C57", "C58", "C55", "C61"]
    },
    {
      "claim": "C69 reports slow metabolism of biochanin A/formononetin/prunetin in human liver microsomes, but these are isoflavones with limited transfer to scopoletin and do not address intestinal glucuronidation; it is a low-weight contradictory signal.",
      "card_ids": ["C69"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C66", "C68", "C71", "C74", "C76", "C77", "C75", "C72"]
    }
  ],
  "evidence_gaps": [
    "No direct scopoletin-specific oral bioavailability or matched oral/IV pharmacokinetic record is available.",
    "No direct scopoletin-specific hepatic or intestinal clearance, UGT phenotyping, or metabolite quantification is available.",
    "L6 records are for other molecules (wogonin, oroxylin A, calycosin, diosmetin, eupatilin, 7-hydroxy-3-(4-fluorophenyl)coumarin, isoflavones), not scopoletin.",
    "Structural transfer from flavonoids/anthocyanins/curcumin/flavonolignans to scopoletin is limited by differences in size, polarity, charge, and scaffold; no coumarin-specific F data are available.",
    "Magnitude of scopoletin first-pass loss is unknown; the low prediction is inferential."
  ],
  "decision_summary": "L1/L2 provide consistent direct low-F outcomes for related phenolic natural products, and L6 adds mechanistic evidence that 7-hydroxy/methoxy phenolics, including a 7-hydroxycoumarin, undergo glucuronidation, supporting presystemic loss for scopoletin's 7-OH. Permeability/no-efflux records for other molecules support absorption but do not establish F>=20%. Prediction remains low with moderate confidence."
}

